<?php
require_once __DIR__.'/../includes/auth.php'; require_role('student');$uid=current_user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['equipment_id'];$pdo->prepare("INSERT INTO maintenance_requests(equipment_id,reported_by,issue_type,description) VALUES(?,?,?,?)")->execute([$id,$uid,$_POST['issue_type'],trim($_POST['description'])]);$admins=$pdo->query("SELECT id FROM users WHERE role='admin' AND is_active=1")->fetchAll();foreach($admins as $a)notify($pdo,(int)$a['id'],'A new equipment issue has been reported.');flash('Issue report submitted.');redirect('report-issue.php');}
$items=$pdo->query("SELECT id,name,equipment_code FROM equipment ORDER BY name")->fetchAll();$s=$pdo->prepare("SELECT m.*,e.name equipment_name FROM maintenance_requests m JOIN equipment e ON e.id=m.equipment_id WHERE m.reported_by=? ORDER BY m.created_at DESC");$s->execute([$uid]);$reports=$s->fetchAll();page_header('Report Equipment Issue','student');?>
<div class="panel mb-4"><h2 class="section-title">Submit an issue</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label">Equipment</label><select class="form-select mb-3" name="equipment_id" required><?php foreach($items as $i):?><option value="<?=$i['id']?>"><?=e($i['name'].' ('.$i['equipment_code'].')')?></option><?php endforeach?></select><label class="form-label">Issue type</label><select class="form-select mb-3" name="issue_type"><option>Damaged Equipment</option><option>Equipment Not Working</option><option>Missing Equipment</option><option>Other Issues</option></select><label class="form-label">Description</label><textarea class="form-control mb-3" name="description" required></textarea><button class="btn btn-primary">Submit report</button></form></div><div class="panel"><h2 class="section-title">My reports</h2><?php foreach($reports as $r):?><p><b><?=e($r['equipment_name'])?></b> · <?=e($r['issue_type'])?> · <?=status_badge($r['status'])?></p><?php endforeach?></div><?php page_footer();?>
